class.description:
Captures the signal passing through an audio bus without changing its output. Attach it with [method FmodAudioEffect.apply_to], then read complete stereo frames with [method get_buffer]. Each [Vector2] contains the left sample in [code]x[/code] and the right sample in [code]y[/code]. Mono input is duplicated; input with more than two channels keeps its first two channels.
When the ring buffer is full, incoming frames are discarded and unread frames are preserved. [method clear_buffer] clears the queue and resets both counters. Changing [member buffer_length] clears queued audio but keeps the counters.
[codeblock]
extends Node

var _capture: FmodAudioEffectCapture = FmodAudioEffectCapture.new()


func _ready() -> void:
	_capture.apply_to(FmodServer.get_main_system().get_master_channel_group())


func _process(_delta: float) -> void:
	if _capture.can_get_buffer(256):
		var frames: PackedVector2Array = _capture.get_buffer(256)
		print(frames[0].x, frames[0].y)
[/codeblock]
